const{test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm');
const root=path.join(__dirname,'..'),source=fs.readFileSync(path.join(root,'experience/observatory.js'),'utf8'),markup=fs.readFileSync(path.join(root,'experience/observatory-markup.js'),'utf8'),ctx={};vm.createContext(ctx);vm.runInContext(source,ctx);const model=ctx.LaunchOrbitModel;
test('Circular orbit at 600 km follows GM/r and negative specific energy',()=>{const vc=Math.sqrt(398600.435507/6971),m=model.describe(1,vc);assert.ok(Math.abs(m.circular-7.5617286)<.0001);assert.equal(m.kind,'NEAR-CIRCULAR ORBIT');assert.ok(m.eccentricity<1e-14);assert.ok(Math.abs(m.energy+398600.435507/(2*6971))<1e-10);assert.equal(m.perigee,6971);});
test('Escape boundary is sqrt(2) times circular speed; suborbital paths are labelled',()=>{const vc=model.describe(1,7.56).circular;assert.equal(model.describe(1,vc*Math.SQRT2).kind,'ESCAPE TRAJECTORY');assert.equal(model.describe(1,vc*1.15).kind,'ELLIPTICAL ORBIT');assert.equal(model.describe(1,4).kind,'EARTH-INTERSECTING PATH');assert.ok(model.describe(1,4).perigee<model.earthRadius);});
test('Mass response and every slider combination yield finite physical results',()=>{const a=model.describe(.5,7),b=model.describe(2,7);assert.equal(b.circular/a.circular,2);for(let mass=.5;mass<=2;mass+=.1)for(let v=4;v<=18;v+=.1){const r=model.describe(mass,v);for(const key of['energy','perigee','circular','escapeSpeed','eccentricity'])assert.ok(Number.isFinite(r[key]));assert.ok(r.perigee>0);}});
test('Reject nonphysical inputs',()=>{for(const [mass,speed]of[[0,7],[-1,7],[1,0],[1,Infinity],[NaN,7],['1',7]])assert.throws(()=>model.describe(mass,speed));});
test('Launch preserves honest claims, native controls and explicit animation control',()=>{assert.doesNotMatch(markup,/500K|1,000\+|Watch the Film|2:18/);assert.match(markup,/DB.length/);assert.match(markup,/Deep.list\(\).length/);assert.match(markup,/Adv.list\(\).length/);assert.match(markup,/type="range"/);assert.match(markup,/Model &amp; assumptions/);assert.match(markup,/id="pe-pause" aria-pressed/);assert.match(source,/prefers-reduced-motion/);assert.match(source,/document.hidden/);assert.match(source,/observer.disconnect\(\)/);assert.match(source,/cancelAnimationFrame\(raf\)/);assert.equal((markup.match(/class="obs-feature"/g)||[]).length,4);});
